// Perspective-projected room surfaces and independent alpha sprites, all in one camera space.
import {drawAssetMedia} from './effect-library.js?v=motion-v70';
import {recordSceneAsset} from './scene-geometry.js?v=motion-v70';
export const portraitRoomSources={historyRoomBackground:'portrait-room-room-v53.png',historyRoomPerson:'portrait-room-person-v53.png',historyRoomVase:'portrait-room-vase-v53.png',historyRoomCloth:'portrait-room-cloth-v53.png'};
export const portraitRoomDefaults={historyRoomEnabled:true,historyRoomSaturation:1,historyRoomWarmth:0,historyRoomVaseBehind:false,historyRoomApplyLater:false,historyRoomSurfaces:[],historyRoomSpeed:1,historyRoomFocal:850,historyRoomPush:600,historyRoomFocusX:.53,historyRoomFocusY:.4,historyRoomStart:0,historyRoomFinish:1,historyRoomPersonDepth:1200,historyRoomVaseDepth:850,historyRoomClothDepth:2000,historyRoomWallDepth:2200,historyRoomPersonX:175,historyRoomPersonY:0,historyRoomPersonWidth:680,historyRoomVaseX:-150,historyRoomVaseY:345,historyRoomVaseWidth:500,historyRoomClothX:135,historyRoomClothY:190,historyRoomClothWidth:190,historyRoomVaseBlur:2.5,historyRoomBackgroundBlur:.3,historyRoomPersonBrightness:.9,historyRoomLight:1,historyRoomShadow:.23};
const clamp=x=>Math.max(0,Math.min(1,x)),lerp=(a,b,q)=>a+(b-a)*q;
export function portraitRoomState(elapsed,duration,input={}){const f={...portraitRoomDefaults,...input},start=clamp(f.historyRoomStart),end=Math.max(start+.001,clamp(f.historyRoomFinish)),u=clamp((elapsed*Math.max(.05,f.historyRoomSpeed)/Math.max(.1,duration)-start)/(end-start)),q=u*u*(3-2*u),focal=Math.max(300,f.historyRoomFocal),depth=Math.max(800,f.historyRoomPersonDepth),push=Math.min(Math.max(0,f.historyRoomPush),Math.min(depth-250,Math.max(250,f.historyRoomVaseDepth)-100)),camera={x:(f.historyRoomFocusX*960-480)*depth/focal*q,y:(f.historyRoomFocusY*540-270)*depth/focal*q,z:push*q,focal};return {u,q,camera};}
export function projectRoomPoint(p,camera){const z=p[2]-camera.z;return [480+(p[0]-camera.x)*camera.focal/z,270+(p[1]-camera.y)*camera.focal/z,z];}
const world=(x,y,z,focal)=>[(x-480)*z/focal,(y-270)*z/focal,z];
export function portraitRoomGeometry(input={}){if(Array.isArray(input.historyRoomSurfaces)&&input.historyRoomSurfaces.length&&input.historyRoomSurfaces.every(m=>Array.isArray(m.points)&&m.points.length===4&&m.points.every(p=>p.length===3&&p.every(Number.isFinite)&&p[2]>40)&&Array.isArray(m.uv)&&m.uv.length===4&&m.uv.every(p=>p.length===2&&p.every(Number.isFinite))))return structuredClone(input.historyRoomSurfaces);const f={...portraitRoomDefaults,...input},D=Math.max(1800,f.historyRoomWallDepth),F=Math.max(300,f.historyRoomFocal),backX=(350-480)*D/F,Y=(420-270)*D/F,top=-950;return [{id:'back-wall',points:[[backX,top,D],[1800,top,D],[1800,Y,D],[backX,Y,D]],uv:[[.457,0],[1,0],[1,.81],[.457,.81]]},{id:'window-wall',points:[[-800,top,1100],[backX,top,D],[backX,Y,D],[-800,Y,1100]],uv:[[0,0],[.457,0],[.457,.81],[0,.81]]},{id:'floor',points:[[-2200,Y,650],[2200,Y,650],[1800,Y,D],[backX,Y,D]],uv:[[0,1],[1,1],[1,.81],[.457,.81]]}];}
function triangle(c,image,src,dst){const [[x0,y0],[x1,y1],[x2,y2]]=src,[[u0,v0],[u1,v1],[u2,v2]]=dst,den=x0*(y1-y2)+x1*(y2-y0)+x2*(y0-y1);if(Math.abs(den)<1e-6)return;const A=(u0*(y1-y2)+u1*(y2-y0)+u2*(y0-y1))/den,B=(v0*(y1-y2)+v1*(y2-y0)+v2*(y0-y1))/den,C=(u0*(x2-x1)+u1*(x0-x2)+u2*(x1-x0))/den,D=(v0*(x2-x1)+v1*(x0-x2)+v2*(x1-x0))/den,E=(u0*(x1*y2-x2*y1)+u1*(x2*y0-x0*y2)+u2*(x0*y1-x1*y0))/den,F=(v0*(x1*y2-x2*y1)+v1*(x2*y0-x0*y2)+v2*(x0*y1-x1*y0))/den;c.save();c.beginPath();const sign=Math.sign((u1-u0)*(v2-v0)-(v1-v0)*(u2-u0))||1;for(const [i,[x,y]]of dst.entries()){const prev=dst[(i+2)%3],next=dst[(i+1)%3],dx1=x-prev[0],dy1=y-prev[1],dx2=next[0]-x,dy2=next[1]-y,len1=Math.hypot(dx1,dy1)||1,len2=Math.hypot(dx2,dy2)||1,n1=[sign*dy1/len1,-sign*dx1/len1],n2=[sign*dy2/len2,-sign*dx2/len2],gain=.85/Math.max(.000001,1+n1[0]*n2[0]+n1[1]*n2[1]),p=[x+(n1[0]+n2[0])*gain,y+(n1[1]+n2[1])*gain];i?c.lineTo(...p):c.moveTo(...p)}c.closePath();c.clip();c.transform(A,B,C,D,E,F);c.drawImage(image,0,0);c.restore();}
function bilerp(points,u,v){return points[0].map((_,k)=>lerp(lerp(points[0][k],points[1][k],u),lerp(points[3][k],points[2][k],u),v));}
function surface(c,image,mesh,camera){const iw=image.naturalWidth||image.width,ih=image.naturalHeight||image.height,N=10;for(let y=0;y<N;y++)for(let x=0;x<N;x++){const q=[[x/N,y/N],[(x+1)/N,y/N],[(x+1)/N,(y+1)/N],[x/N,(y+1)/N]],p=q.map(([u,v])=>projectRoomPoint(bilerp(mesh.points,u,v),camera)),uv=q.map(([u,v])=>{const p=bilerp(mesh.uv,u,v);return [p[0]*iw,p[1]*ih]});if(p.some(p=>p[2]<40))continue;for(const a of [[0,1,2],[0,2,3]])triangle(c,image,a.map(i=>uv[i]),a.map(i=>p[i]));}}
function spriteRect(rect,depth,camera){const [x,y,w,h]=rect,A=projectRoomPoint(world(x,y,depth,camera.focal),camera),B=projectRoomPoint(world(x+w,y+h,depth,camera.focal),camera);return [A[0],A[1],B[0]-A[0],B[1]-A[1]];}
let roomBuffer;
export function paintPortraitRoom(c,elapsed,duration,images,input={}){const f={...portraitRoomDefaults,...input},media=slot=>images[f.historySourceBindings?.[slot]||slot],room=media('historyRoomBackground'),person=media('historyRoomPerson');if(!f.historyRoomEnabled||!(room?.naturalWidth||room?.width)||!(person?.naturalWidth||person?.width))return false;const state=portraitRoomState(elapsed,duration,f),cam=state.camera;c.save();c.fillStyle='#151515';c.fillRect(0,0,960,540);roomBuffer||=Object.assign(document.createElement('canvas'),{width:960,height:540});const roomContext=roomBuffer.getContext('2d');roomContext.clearRect(0,0,960,540);roomContext.imageSmoothingEnabled=true;roomContext.imageSmoothingQuality='high';for(const mesh of portraitRoomGeometry(f))surface(roomContext,room,mesh,cam);c.filter=`sepia(${f.historyRoomWarmth}) saturate(${f.historyRoomSaturation}) brightness(${Math.max(.1,f.historyRoomLight)}) blur(${Math.max(0,f.historyRoomBackgroundBlur)}px)`;c.drawImage(roomBuffer,0,0);c.filter='none';function layer(slot,rect,depth,blur=0,brightness=1){const im=media(slot);if(!(im?.naturalWidth||im?.width))return;const r=spriteRect(rect,Math.max(cam.z+80,depth),cam);c.save();c.filter=`saturate(${f.historyRoomSaturation}) brightness(${brightness}) blur(${Math.max(0,blur)}px)`;drawAssetMedia(c,im,r,f,elapsed);c.restore();recordSceneAsset(c,{id:f.historySourceBindings?.[slot]||slot,kind:'image',assetSlot:f.historySourceBindings?.[slot]||slot,name:f.historySourceBindings?.[slot]||slot},r);return r;}
const cloth=media('historyRoomCloth');if(cloth)layer('historyRoomCloth',[f.historyRoomClothX,f.historyRoomClothY,f.historyRoomClothWidth,f.historyRoomClothWidth*(cloth.naturalHeight||cloth.height)/(cloth.naturalWidth||cloth.width)],f.historyRoomClothDepth);
c.save();const shadow=spriteRect([260,440,410,80],f.historyRoomPersonDepth+70,cam);c.filter='blur(18px)';c.fillStyle=`rgba(0,0,0,${clamp(f.historyRoomShadow)})`;c.beginPath();c.ellipse(shadow[0]+shadow[2]/2,shadow[1]+shadow[3]/2,Math.abs(shadow[2]/2),Math.abs(shadow[3]/2),0,0,Math.PI*2);c.fill();c.restore();
const drawVase=()=>{const vase=media('historyRoomVase');if(vase)layer('historyRoomVase',[f.historyRoomVaseX,f.historyRoomVaseY,f.historyRoomVaseWidth,f.historyRoomVaseWidth*(vase.naturalHeight||vase.height)/(vase.naturalWidth||vase.width)],f.historyRoomVaseDepth,f.historyRoomVaseBlur);};if(f.historyRoomVaseBehind)drawVase();layer('historyRoomPerson',[f.historyRoomPersonX,f.historyRoomPersonY,f.historyRoomPersonWidth,f.historyRoomPersonWidth*(person.naturalHeight||person.height)/(person.naturalWidth||person.width)],f.historyRoomPersonDepth,0,f.historyRoomPersonBrightness);
if(!f.historyRoomVaseBehind)drawVase();c.restore();return state;}
